import xml.etree.ElementTree as ET
from mpc_cbf_node import *
import numpy as np

def parse_ros_launch_params(file_path):
    """
    Parses a ROS launch file and returns a dictionary of parameters.
    """
    params = {}
    
    try:
        tree = ET.parse(file_path)
        root = tree.getroot()

        # Find all <param> tags within the XML
        for param in root.iter('param'):
            name = param.get('name')
            value = param.get('value')

            if name is not None and value is not None:
                # Convert numeric strings to actual int/float types
                params[name] = convert_value(value)
                
        return params

    except ET.ParseError as e:
        print(f"Error parsing XML: {e}")
    except FileNotFoundError:
        print(f"File not found: {file_path}")
    
    return params

def convert_value(val):
    """Helper to cast strings to numeric types if possible."""
    # Try integer
    try:
        if val.isdigit() or (val.startswith('-') and val[1:].isdigit()):
            return int(val)
    except ValueError:
        pass
    
    # Try float
    try:
        return float(val)
    except ValueError:
        pass
    
    # Return as string (or boolean check) if not numeric
    if val.lower() == 'true': return True
    if val.lower() == 'false': return False
    
    return val


